import { buildSectionQuestBoard, createQuestSeenStore, type SectionQuestBoard } from './sectionQuests';

export const COMPLIANCE_QUEST_SEEN_STORAGE_KEY = 'ci_compliance_quests_seen_v1';

export type ComplianceQuestInput = {
  hasAssessment?: boolean;
  overallReadinessScore?: number | null;
  closedGapCount?: number;
  totalGapCount?: number;
  hasReportGoal?: boolean;
  exportApplicable?: boolean;
};

const LEVEL_META = {
  1: { label: 'Starter', caption: 'Finish footprint before deep compliance.' },
  2: { label: 'Checking', caption: 'Close the top readiness gaps.' },
  3: { label: 'Report-ready', caption: 'Pick one disclosure pack.' },
  4: { label: 'Compliance champ', caption: 'Scores look healthy — download when needed.' },
} as const;

export function deriveComplianceQuests(input: ComplianceQuestInput): SectionQuestBoard {
  const score = input.overallReadinessScore == null ? 0 : Number(input.overallReadinessScore);
  const closed = Number(input.closedGapCount) || 0;
  const total = Number(input.totalGapCount) || 0;
  const gapsClosedEnough = total === 0 ? Boolean(input.hasAssessment) : closed >= Math.min(3, total);

  return buildSectionQuestBoard(
    [
      {
        id: 'baseline_first',
        title: 'Have a footprint',
        description: 'Compliance scores need a carbon baseline first.',
        complete: Boolean(input.hasAssessment),
        path: '/carbon-footprint?section=start-assessment',
        ctaLabel: 'Footprint',
      },
      {
        id: 'check_readiness',
        title: 'Run readiness check',
        description: 'Open the 3-step checklist on this hub.',
        complete: score > 0 || closed > 0,
        path: '/compliance',
        ctaLabel: 'Checklist',
      },
      {
        id: 'close_top_gaps',
        title: 'Close top gaps',
        description: 'Finish the first readiness steps (upload or answer).',
        complete: gapsClosedEnough || score >= 50,
        path: '/compliance',
        ctaLabel: 'Fix gaps',
      },
      {
        id: 'pick_report',
        title: 'Pick report goal',
        description: 'Choose buyer, bank, or export on Disclosure reports.',
        complete: Boolean(input.hasReportGoal),
        path: '/reporting',
        ctaLabel: 'Reporting',
      },
      {
        id: 'healthy_score',
        title: 'Healthy readiness',
        description: 'Reach about 65% overall readiness for downloads.',
        complete: score >= 65,
        path: '/reporting',
        ctaLabel: 'Open reports',
      },
    ],
    LEVEL_META
  );
}

const store = createQuestSeenStore(COMPLIANCE_QUEST_SEEN_STORAGE_KEY);
export const markComplianceQuestSeen = store.markSeen;
export const detectNewComplianceQuestCelebrations = store.detectNewCelebrations;
