import { useQuery } from '@tanstack/react-query';
import { queryKeys } from '../../constants/queryKeys';
import ApiService from '../../services/api';

const WORKSPACE_STALE_MS = 3 * 60_000;

export function useMsmeProfileQuery(enabled = true) {
  return useQuery({
    queryKey: queryKeys.msme.profile,
    queryFn: () => ApiService.getMSMEProfile(),
    enabled,
    staleTime: WORKSPACE_STALE_MS,
    refetchOnWindowFocus: false,
  });
}

export function useMsmeStatsQuery(enabled = true) {
  return useQuery({
    queryKey: queryKeys.msme.stats,
    queryFn: async () => {
      try {
        return await ApiService.getMSMEStats();
      } catch {
        return null;
      }
    },
    enabled,
    staleTime: WORKSPACE_STALE_MS,
    refetchOnWindowFocus: false,
  });
}
